/**
 * The twenty-five natures, in PokeAPI id order.
 *
 * Purely cosmetic here — a companion is dealt one at hatch and nothing reads it
 * again. The games use natures to nudge two stats by 10%, and this app has no
 * stats to nudge, so carrying the mechanic across would mean inventing one.
 */
export const NATURES = ["hardy","bold","modest","calm","timid","lonely","docile","mild","gentle","hasty","adamant","impish","bashful","careful","rash","jolly","naughty","lax","quirky","naive","brave","relaxed","quiet","sassy","serious"] as const;
export type Nature = (typeof NATURES)[number];

/** Korean names, so the panel never shows "sassy" to a Korean reader. */
export const NATURE_KO: Record<string, string> = {
  "hardy": "노력",
  "bold": "대담",
  "modest": "조심",
  "calm": "차분",
  "timid": "겁쟁이",
  "lonely": "외로움",
  "docile": "온순",
  "mild": "의젓",
  "gentle": "얌전",
  "hasty": "성급",
  "adamant": "고집",
  "impish": "장난꾸러기",
  "bashful": "수줍음",
  "careful": "신중",
  "rash": "덜렁",
  "jolly": "명랑",
  "naughty": "개구쟁이",
  "lax": "촐랑",
  "quirky": "변덕",
  "naive": "천진난만",
  "brave": "용감",
  "relaxed": "무사태평",
  "quiet": "냉정",
  "sassy": "건방",
  "serious": "성실"
};

export function speciesName(id: number, lang: 'ko' | 'en' = 'ko'): string {
  const n = NAMES[id];
  if (!n) return `#${id}`;
  return lang === 'ko' ? n[0] : n[1];
}
